  // Recherche combobox : on TAPE et la LISTE suit — matche name / city_name /
  // iata_code (insensible aux accents), les villes d'abord puis leurs aéroports.
  chercherPlaces: function (q, type) {
    var norm = function (t) { return t.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, ''); };
    var n = norm(q || '');
    var out = this.places.filter(function (p) {
      if (type && p.type !== type) return false;
      if (!n) return true;
      return norm(p.name).indexOf(n) === 0 || norm(p.city_name).indexOf(n) === 0 || norm(p.iata_code) === n ||
             norm(p.name).indexOf(' ' + n) !== -1 || norm(p.city_name).indexOf(' ' + n) !== -1;
    });
    out.sort(function (a, b) { return a.type === b.type ? 0 : (a.type === 'city' ? -1 : 1); });
    return out.slice(0, 8);
  },

