comparatifMoyenne: function () {
  var c = this.comparatifJour;
  var m = c.reduce(function (s, l) { return s + (l.opodo - l.nous) / l.opodo; }, 0) / c.length;
  return Math.round(m * 1000) / 10;   // en %
},

