  logoCompagnie: function (ref, px) {
    var c = typeof ref === "string"
      ? this.compagnies.find(function (x) { return x.iata === ref || x.nom === ref; })
      : ref;
    px = px || 34;
    if (!c) c = { iata: "✈", nom: "Compagnie", couleur: "#0C7F54" };
    // VRAI logo auto-hébergé (ui/assets/vendor/airlines) — repli monogramme si absent
    var fb = "this.style.display='none';this.parentNode.style.background='" + c.couleur + "';this.parentNode.style.color='" + (c.encre || '#fff') + "';this.parentNode.textContent='" + c.iata + "'";
    return '<span title="' + c.nom + '" aria-label="' + c.nom + '" style="display:inline-flex;align-items:center;justify-content:center;flex:none;width:' + px + 'px;height:' + px + 'px;border-radius:9px;background:#fff;font-size:' + Math.round(px * 0.34) + 'px;font-weight:800;box-shadow:0 2px 8px rgba(15,42,36,.14);overflow:hidden"><img src="../assets/vendor/airlines/' + c.iata + '.png" alt="' + c.nom + '" style="width:78%;height:78%;object-fit:contain" onerror="' + fb + '"></span>';
  },
  logoLockup: function (c, h) {
    return '<img src="../assets/vendor/airlines/' + c.iata + '-lockup.svg" alt="' + c.nom + '" title="' + c.nom + '" style="height:' + (h || 20) + 'px;width:auto;max-width:96px;object-fit:contain" onerror="this.outerHTML=window.PEC_DATA.logoCompagnie(\'' + c.iata + '\', ' + (h || 20) + ')">';
  },

  /* ── (10/09 — lot 8, constat C33) LES CODES PROMO FLY SONT UNE TABLE ────────────────────────────────────────
     Deux codes étaient écrits dans le référentiel, dont un expiré depuis des semaines et présenté « du moment »
     au client. Ils se CRÉENT (manager 26), ils portent une vraie date de fin (ISO, jamais « 31 août »), et ils
     se désactivent. Zéro code au démarrage : c'est l'état honnête entre deux opérations. ── */
  codesPromoFlyGet: function () {
    var l; try { l = JSON.parse(localStorage.getItem('pec-codes-promo-fly') || '[]') || []; } catch (e) { l = []; }
    return (this.promoAstuces.codes || []).concat(l);
  },
  codePromoFlyActif: function (c) {
    if (!c || c.actif === false) return false;
    if (!c.finISO) return true;
    return new Date(c.finISO + 'T23:59:59') >= new Date();
  },
  codesPromoFlyActifs: function () { var d = this; return this.codesPromoFlyGet().filter(function (c) { return d.codePromoFlyActif(c); }); },
  codePromoFlyCreer: function (o, par) {
    o = o || {};
    var code = String(o.code || '').trim().toUpperCase().replace(/[^A-Z0-9]/g, '');
    if (code.length < 3) return { ok: false, motif: 'Le code fait au moins 3 caractères (lettres et chiffres).' };
    if (this.codesPromoFlyGet().some(function (x) { return x.code === code; })) return { ok: false, motif: 'Le code ' + code + ' existe déjà.' };
    var remise = parseFloat(String(o.remise || '').replace(',', '.'));
    if (!(remise > 0)) return { ok: false, motif: 'La remise doit être un montant positif en euros.' };
    if (!/^\d{4}-\d{2}-\d{2}$/.test(String(o.finISO || ''))) return { ok: false, motif: 'Une date de fin est obligatoire — un code sans échéance ne s\'éteint jamais.' };
    if (new Date(o.finISO + 'T23:59:59') < new Date()) return { ok: false, motif: 'Cette date de fin est déjà passée.' };
    var minTotal = parseFloat(String(o.minTotal || '').replace(',', '.')) || 0;
    if (minTotal && remise >= minTotal) return { ok: false, motif: 'La remise ne peut pas atteindre le minimum d\'achat.' };
    var c = { code: code, desc: String(o.desc || '').trim() || (remise + ' € de remise'), remise: remise,
      minTotal: minTotal || null, minVoyageurs: parseInt(o.minVoyageurs, 10) || null,
      finISO: o.finISO, fin: new Date(o.finISO + 'T12:00:00').toLocaleDateString('fr-FR', { day: 'numeric', month: 'long' }),
      actif: true, creeAt: Date.now(), creePar: par || null };
    var l; try { l = JSON.parse(localStorage.getItem('pec-codes-promo-fly') || '[]') || []; } catch (e) { l = []; }
    l.unshift(c);
    try { localStorage.setItem('pec-codes-promo-fly', JSON.stringify(l)); } catch (e2) { return { ok: false, motif: 'Stockage plein sur cet appareil — le code n\'a pas été enregistré.' }; }
    this._journal('code_promo_fly_cree', code, { par: par, remise: remise, fin: c.finISO, minTotal: c.minTotal });
    try { window.dispatchEvent(new CustomEvent('pec-bus')); } catch (e3) {}
    return { ok: true, codePromo: c };
  },
  codePromoFlyDesactiver: function (code, par) {
    var l; try { l = JSON.parse(localStorage.getItem('pec-codes-promo-fly') || '[]') || []; } catch (e) { l = []; }
    var c = l.filter(function (x) { return x.code === code; })[0];
    if (!c) return { ok: false, motif: 'Code inconnu (ou code du référentiel, non désactivable).' };
    c.actif = false; c.desactiveAt = Date.now(); c.desactivePar = par || null;
    try { localStorage.setItem('pec-codes-promo-fly', JSON.stringify(l)); } catch (e2) { return { ok: false, motif: 'Stockage plein — le code reste actif.' }; }
    this._journal('code_promo_fly_desactive', code, { par: par });
    try { window.dispatchEvent(new CustomEvent('pec-bus')); } catch (e3) {}
    return { ok: true };
  },
  /* Code promo au paiement : validation UNIQUE, mêmes règles partout — et la date de fin est une VRAIE date. */
  validerCodePromo: function (saisie, totalEuros, nbVoyageurs) {
    var saisi = String(saisie || '').trim().toUpperCase();
    var c = this.codesPromoFlyGet().filter(function (x) { return x.code === saisi; })[0];
    if (!c) return { ok: false, message: "Code inconnu ou expiré." };
    if (!this.codePromoFlyActif(c)) return { ok: false, message: c.actif === false ? "Ce code n'est plus valable." : "Ce code a expiré le " + (c.fin || c.finISO) + "." };
    if (c.minTotal && totalEuros < c.minTotal) return { ok: false, message: "Ce code s'applique dès " + c.minTotal + " € d'achat." };
    if (c.minVoyageurs && nbVoyageurs < c.minVoyageurs) return { ok: false, message: "Ce code s'applique dès " + c.minVoyageurs + " voyageurs." };
    return { ok: true, code: c.code, remise: c.remise, message: "Code " + c.code + " appliqué : −" + c.remise + " €." };
  },

