      taux: { fenetreJours: 90, ventesMin: 20, alerte: 0.03, retenue: 0.06, blocage: 0.10, ponderationContrefacon: 5 },
      retenue: { fraction: 0.10, joursLiberation: 60 },
      abusClient: { fenetreJours: 180, seuil: 3 },
