    var max = Math.round((som('debit') - som('recredit')) * 100) / 100;
    if (m > max + 0.004) return { ok: false, motif: 'On ne re-crédite que ce que ce bon d’achat a réglé' + (refCommande ? ' sur ' + refCommande : '') + ' : ' + this.eur(max) + ' au plus.' };
    var l = this.bonsGet(), b = l.filter(function (x) { return x.code === b0.code; })[0];
