    if (b.expireLe && Date.now() > b.expireLe) { var ex = new Date(); ex.setMonth(ex.getMonth() + this.bonsRef().validiteMois); b.expireLe = ex.getTime(); b.prolongeLe = Date.now(); }
    b.mouvements = (b.mouvements || []).concat([{ type: 'recredit', montant: m, at: Date.now(), commande: refCommande || null, motif: motif || 'remboursement', par: par || 'manager' }]);
