      r.statut = 'close'; r.motif = 'retour_absent'; r.motifLabel = (self.reclamationMotif('retour_absent') || {}).label || 'Retour jamais renvoyé';
      if (r.debit && r.debit.statut === 'gele') { r.debit.statut = 'annule'; r.debit.annuleAt = Date.now(); }
      r.journal.push({ evt: 'expiree', par: 'systeme', at: Date.now(), detail: 'retour jamais déposé' });
